const webhookData = $('Webhook').first().json;
const target = $('Execute a SQL query').first().json;
const imageBase64 = webhookData.body.photo;
const clue = target.clue || target.hints || target.base_clue || target.description || '';

return {
  model: "llava",
  stream: false,
  messages: [{
    role: "user",
    content: `You are a location verification system. Does this image show ${target.name}? Clue: ${clue}. Answer with ONLY yes or no.`,
    images: [imageBase64]
  }]
};

const verified = $('HTTP Request (Ollama AI)').first().json.message.content.toLowerCase().includes('yes');
const currentLocation = $('Execute a SQL query').first().json;

return {
  verified,
  aiMessage: $('HTTP Request (Ollama AI)').first().json.message.content,
  currentLocationId: currentLocation.id,
  nextLocationId: verified ? (currentLocation.id ? currentLocation.id + 1 : 2) : null
};

const buildResp = $('Build Response').first().json;
const nextLocResult = $('Get Next Location').first();

// Handle when Get Next Location returns no data
if (!nextLocResult || !nextLocResult.json) {
  return {
    success: buildResp.verified,
    verified: buildResp.verified,
    message: buildResp.aiMessage,
    nextTargetId: null,
    nextMission: null
  };
}

const nextLocData = nextLocResult.json;
const nextLoc = Array.isArray(nextLocData) && nextLocData.length > 0 ? nextLocData[0] : (nextLocData && nextLocData.id ? nextLocData : null);

return {
  success: buildResp.verified,
  verified: buildResp.verified,
  message: buildResp.aiMessage,
  nextTargetId: nextLoc && nextLoc.id ? String(nextLoc.id) : null,
  nextMission: nextLoc && nextLoc.name ? `Head to ${nextLoc.name}. ${nextLoc.clue}` : null
};
